    "daniel_verse": 20,
    "target_book": "Job",
    "target_chapter": 12,
    "target_verse_start": 13,
    "target_verse_end": 13,
    "note": "With God are wisdom and might; he has counsel and understanding. In Daniel's case, wisdom is never merely intellectual achievement — it is the fruit of fearing God in a context deliberately designed to produce Babylonian servants rather than covenant ones. Every demonstration of his wisdom is simultaneously a testimony to the God who gave it: Daniel's understanding cannot be explained by his Babylonian training alone, which is precisely the point the text makes. The wise men of the empire operated without this divine source and were repeatedly found wanting when the mysteries of heaven were placed before them."
