    "target_book": "Exodus",
    "target_chapter": 20,
    "target_verse_start": 4,
    "target_verse_end": 5,
    "note": "The second commandment forbids making and bowing to images. Daniel's fidelity to the covenant law is the spine of his moral resistance throughout the entire book. His refusals — of the king's food, of pagan worship, of abandoning prayer — are all covenant-shaped choices, not personal eccentricities. He does not invent a private ethic; he enacts the commitments of Deuteronomy in an environment specifically engineered to dissolve them. Every connection to the Mosaic law in Daniel's story underscores that the same covenant that defined Israel in the wilderness now defines one faithful man in the heart of the greatest empire on earth."
