    "daniel_verse": 9,
    "target_book": "Matthew",
    "target_chapter": 26,
    "target_verse_start": 59,
    "target_verse_end": 60,
    "note": "The chief priests seeking false testimony against Jesus. The theology of testing and refinement runs throughout Daniel in both narrative and vision. The furnace, the den, the dietary test, the political conspiracies — none of these are accidental. They are the instruments by which God confirms, displays, and deepens the faith of his servants. The cross-reference here connects Daniel's experience of testing to a wider canonical witness that suffering is not the absence of divine care but often its most concentrated expression: God is most deeply at work in his servants precisely when the heat is most extreme and the lions are nearest."
