    "target_chapter": 42,
    "target_verse_start": 10,
    "target_verse_end": 12,
    "note": "Job's restoration after his humiliation — the reversal pattern. Nebuchadnezzar's trajectory across Daniel chapters 1 through 4 is one of the Old Testament's most fully developed portraits of God humbling the proud: from arrogant world-conqueror who reduces Daniel and his companions to a re-education project, through successive encounters with divine wisdom that he cannot explain away, to seven years of animal-like madness, and finally to the doxology of Daniel 4:34-37. Each encounter with Daniel's God strips away another layer of Nebuchadnezzar's self-sufficiency. This cross-reference marks one stage in that arc — the greatest king in the world being schooled by the prisoners he sought to transform into Babylonians."
