    "target_book": "Ezra",
    "target_chapter": 1,
    "target_verse_start": 7,
    "target_verse_end": 11,
    "note": "Cyrus later restoring those same vessels to Jerusalem. Cyrus the Great stands at the hinge between Daniel's Babylonian ministry and the restoration era. Isaiah had named him over a century before his birth as the one God would use to release the captives; Jeremiah's seventy-year clock was fulfilled in his first year. Daniel's longevity until Cyrus's rise means he spanned the entire arc of the exile — from the beginning of the judgment to the beginning of the restoration. His survival is itself a testimony: the God who sent his people into exile also named the man who would bring them home, and Daniel lived to see both ends of that promise."
