    "target_verse_start": 26,
    "target_verse_end": 27,
    "note": "Sinning deliberately after receiving knowledge of the truth — fearful judgment remains. The fall of Babylon, which Daniel witnesses at the end of chapter 5, is one of the Old Testament's most dramatic confirmations of prophetic reliability: Isaiah and Jeremiah had announced Babylon's destruction in specific and striking terms, and Daniel was present to see the handwriting appear on the wall and the city fall that very night. The prophetic and historical strands are woven together in Daniel's person: he is both the interpreter of the divine verdict and the eyewitness to its execution, and his presence at both moments validates the entire prophetic enterprise."
