    "target_book": "Exodus",
    "target_chapter": 31,
    "target_verse_start": 18,
    "target_verse_end": 18,
    "note": "God writing with his own finger — echoing the inscription of the law at Sinai. Daniel's great prayer of confession in chapter 9 is one of the most theologically complete acts of covenantal self-identification in the Old Testament. Daniel does not pray as a righteous man petitioning on behalf of sinners; he identifies himself fully with the covenant community — 'we have sinned' — even though his personal righteousness was recognized even by God through Ezekiel. His confession reflects a profound understanding that Israel's suffering was deserved, that God's justice was vindicated, and that the only basis for appeal was not Israel's faithfulness but God's own steadfast love and his commitment to his own name."
