    "target_verse_start": 29,
    "target_verse_end": 30,
    "note": "Solomon's prayer that God would hear prayers offered toward this house. Daniel's prayer life is one of the most consistent features of his character across all twelve chapters — from the urgent night prayer of chapter 2, through the extended covenantal confession of chapter 9, to the three-week fast of chapter 10. Prayer for Daniel is not a last resort when all else has failed but a first orientation to every situation. His three-times-daily discipline facing Jerusalem was not suspended even when it meant facing the lions' den in chapter 6, which proves that prayer was not merely instrumental for Daniel but constitutive of his identity as a servant of the living God."
