    "target_verse_end": 20,
    "note": "The beast was captured and thrown into the lake of fire. The deliverance miracles of Daniel form a theology of divine protection that cannot be separated from the theology of covenant faithfulness. God does not promise his servants immunity from danger — Daniel's companions are thrown into the furnace; Daniel is cast into the lions' den. What he promises is his presence within the danger and his ultimate sovereignty over the outcome. These miracles are not spectacles arranged for the amusement of pagan onlookers but testimonies to the watching empires that the God of Israel is not a regional deity who lost at Carchemish but the living God who governs every nation, every fire, and every beast."
