    "note": "They will see the Son of Man coming on the clouds of heaven with power and glory. Daniel 7's vision of the Son of Man coming on the clouds of heaven to receive everlasting dominion from the Ancient of Days is the most directly Christological passage in the Old Testament prophets. Jesus claimed this title and applied this precise imagery to himself at his trial before the Sanhedrin, making Daniel 7 the exegetical key to understanding his self-disclosure as both fully human and sharing divine authority. The Son of Man receives what Adam forfeited — dominion over creation — and does so not by conquest but by presentation before the throne, a union the New Testament identifies as the Incarnation and the exaltation following the cross."
