    "target_book": "1 Corinthians",
    "target_chapter": 6,
    "target_verse_start": 2,
    "target_verse_end": 3,
    "note": "The saints will judge the world and even angels. The angelic activity in Daniel is among the most developed in the entire Old Testament, anticipating the richer angelology of Revelation and the New Testament. Gabriel comes to give Daniel understanding of the vision; Michael stands as the great prince contending on behalf of Israel in cosmic conflict. These are not decorative figures but active agents in a spiritual war that runs parallel to and ultimately governs the political history Daniel is living through. His visions reveal that Babylon, Persia, and Greece are not merely political entities but positions in a cosmic contest whose verdict is being rendered in the heavenly court."
