    "target_chapter": 13,
    "target_verse_start": 7,
    "target_verse_end": 7,
    "note": "Strike the shepherd and the sheep will be scattered. This connection places Daniel within the larger canonical witness of Scripture, confirming that his life and prophecies were not isolated episodes but deeply embedded in the long story of God's covenant faithfulness to Israel and, through Israel, to all the nations. The passage from Zechariah 13 provides a parallel thread — whether typological, prophetic, or thematic — that enriches the understanding of what God was accomplishing through Daniel's extraordinary ministry in Babylon, where the covenant, the exile, divine sovereignty over empires, and the promise of ultimate restoration all converge in a single servant's life and vision."
