    "note": "When you see the abomination of desolation standing where it ought not to be. Daniel's positioning within Babylonian and then Persian imperial structures gives his book a unique theological vantage point: he is simultaneously inside the empire and critiquing it from within. The visions of chapters 2, 7, and 8 show successive empires rising and falling under divine governance; the narratives of chapters 1 through 6 show a covenant servant maintaining faithfulness within those same structures. The combination is not accidental — Daniel shows his readers both the broad picture of God's sovereignty over all of history's empires and the granular shape of what covenant faithfulness looks like inside that history."
