    "target_chapter": 32,
    "target_verse_start": 32,
    "target_verse_end": 33,
    "note": "If not blot me out of your book — the book of life in Moses's intercession. The imagery of names written in or blotted from the book of life runs from Moses's intercession through Daniel 12 and into the New Testament's final visions. Daniel 12:1 — those found written in the book will be delivered — gives eschatological weight to what had been a metaphor of divine record-keeping. It means that Daniel's promised deliverance in the time of unprecedented trouble is not a political calculation but a covenantal one: God knows those who are his, and he will not lose them when the final storm breaks."
