    "target_book": "John",
    "target_chapter": 5,
    "target_verse_start": 28,
    "target_verse_end": 29,
    "note": "All who are in the tombs will hear his voice and come out — resurrection to life or judgment. Daniel 12:2 is the most explicit Old Testament statement of a final bodily resurrection of both the righteous and the wicked, and it stands as the book's ultimate answer to the problem of unjust suffering. Against the backdrop of all Daniel has witnessed — empires crushing the faithful, the three young men in the furnace, Daniel in the den, the righteous dying without vindication — the resurrection promise is the final word. The book does not end with political deliverance alone but with cosmic justice: those who sleep in the dust will awake, and those who turned many to righteousness will shine like the stars of heaven forever."
