    "note": "The holy city trampled for forty-two months — the same desolation period. The abomination of desolation is among the most cited prophetic images in all of Scripture: Jesus references it explicitly in the Olivet Discourse (Matthew 24:15), Paul's lawless one who sits in the temple echoes it in 2 Thessalonians 2, and Revelation's trampling of the holy city is built on its foundation. Daniel is the root from which all these branches grow. The image was first given concrete historical form in Antiochus IV Epiphanes's desecration of the temple in 167 BC, but Daniel's language consistently points beyond that single fulfillment toward an ultimate crisis at the end of the age — a feature that drove Jesus, Paul, and John to draw on it for their own eschatological teaching."
